sys_script_include.script:
var DirectoryGroupAPI = Class.create();
DirectoryGroupAPI.CONSTANTS = {
    API_CONFIG: {
        GET_USER_GROUPS: {
            path: "/admin/directory/v1/groups",
            httpMethod: "GET",
            queryParams: ["userKey", "pageToken", "maxResults", "query"]
        }
    }
};
DirectoryGroupAPI.prototype = Object.extend(new x_neyu_google_nyu.RestUtil(), {
    initialize: function() {
        this.oauthProvider = "d6e39ac42b280f108a69f0dcce91bfdb";
        this.providerProfile = "f03492482b280f108a69f0dcce91bffc";
        this.credential = gs.getProperty("x_neyu_google_nyu.directory.api.credential.id");
        this.aliasId = "1249fca42b94c3508a69f0dcce91bf0f";
    },

    /**
     * Retrieves all Google Groups that a specific user is a member of.
     * * This method uses the `userKey` (email or unique ID) to query the Google 
     * Directory API and returns a list of group memberships associated with that user.
     * * @param {string} userKey - The user's primary email address, alias, or unique user ID.
     * * @returns {Object} Standardized Response Object
     * @returns {boolean} return.error - True if `userKey` is missing or the API request fails.
     * @returns {number} return.status - The HTTP status code (e.g., 200, 403, 500).
     * @returns {string} return.errorMessage - Description of the error (null if successful).
     * @returns {string} return.responseBody - The raw JSON string containing the groups list.
     * **Note:** Must be parsed using `JSON.parse()` before use.
     * * @example
     * const result = utils.getUserGroups('employee.name@company.com');
     * if (!result.error) {
     * const data = JSON.parse(result.responseBody);
     * // Google API returns an object with a 'groups' array
     * (data.groups || []).forEach(group => {
     * gs.info("Member of: " + group.name);
     * });
     * }
     */
    getUserGroups: function({
        userKey = null,
        maxResults = 200,
        pageToken = null,
        query = null
    } = {}) {
        gs.info(`[getUserGroups] userKey: ${userKey}` +
            `\nquery: ${query}` +
            `\nmaxResults: ${maxResults}` +
            `\npageToken: ${pageToken}`);

        this.ensureToken(this.credential, this.oauthProvider, this.providerProfile);

        const queryParams = {};
        if (!gs.nil(userKey)) {
            queryParams["userKey"] = userKey;
        }
        if (!gs.nil(maxResults)) {
            queryParams["maxResults"] = maxResults;
        }
        if (!gs.nil(pageToken)) {
            queryParams["pageToken"] = pageToken;
        }
        if (!gs.nil(query)) {
            queryParams["query"] = query;
        }

        const config = DirectoryGroupAPI.CONSTANTS.API_CONFIG.GET_USER_GROUPS;
        const requestConfig = {
            ...config,
            queryParams,
            aliasId: this.aliasId
        };

        const response = this.execute(requestConfig, "getUserGroups");

        if (response.error) {
            gs.error("[getUserGroups] There was an error returned from " +
                "the Google Directories API.\nResponse: " + JSON.stringify(response));
        }

        return {
            ...response
        };
    },

    type: 'DirectoryGroupAPI'
});
